registerExercises('biologia', '1', [
  {st: '¿Cuál de los siguientes ítems corresponde a tres características de TODOS los seres vivos?', opts: ["Mitosis, homeostasis, metabolismo", "Crecimiento, respiración aeróbica, reproducción", "Metabolismo, evolución, irritabilidad", "Fotosíntesis, irritabilidad, homeostasis"], c: 2, ex: "Metabolismo + evolución + irritabilidad las cumplen TODOS. → <b>Las otras:</b> (A) mitosis NO en procariotas (fisión binaria); (B) respiración aeróbica NO en anaerobios estrictos; (D) fotosíntesis solo en autótrofos."},
  {st: 'La homeostasis se refiere a:', opts: ["Reproducirse de manera constante para sostener la población frente a los cambios externos", "Mantener el medio interno relativamente constante frente a los cambios externos", "Sintetizar moléculas orgánicas de manera constante a partir de los nutrientes del medio", "Adaptar la estructura del organismo, de generación en generación, al ambiente externo"], c: 1, ex: "Homeostasis = mantener T, pH, glucemia, osmolaridad estables. Ej: insulina al consumir azúcar. → <b>Las otras:</b> (A) reproducción es otro proceso, no regula el medio interno; (C) la síntesis de moléculas es metabolismo; (D) adaptarse de generación en generación es evolución, no homeostasis."},
  {st: 'Ordenar de menor a mayor: Nitrógeno, aminoácido, enzima, célula, hígado.', opts: ["Nitrógeno, aminoácido, enzima, célula, hígado", "Enzima, célula, nitrógeno, hígado, aminoácido", "Célula, nitrógeno, hígado, enzima, aminoácido", "Hígado, enzima, célula, aminoácido, nitrógeno"], c: 0, ex: "Niveles: átomo (N) → molécula (aminoácido) → macromolécula/proteína (enzima) → célula → órgano (hígado). → Por qué las otras están mal: desordenan las jerarquías biológicas."},
  {st: '¿Cuál situación se vincula con homeostasis?', opts: ["La muerte de organismos aerobios en una laguna sin oxígeno disuelto", "La reproducción ilimitada de un cultivo cuando aumenta la cantidad de nutrientes", "El marchitamiento de los girasoles tras una falta prolongada de luz", "La liberación de insulina al consumir una golosina para regular la glucemia"], c: 3, ex: "Insulina mantiene glucemia en rango estable a pesar del input variable → homeostasis clásica. → <b>Las otras:</b> son ejemplos de fallo o de respuesta NO homeostática: (A) es una muerte por falta de oxígeno; (B) es un crecimiento ilimitado, sin regulación; (C) es un marchitamiento por falta de luz."},
  {st: '¿Cuántos dominios biológicos se reconocen?', opts: ["2 (procariota y eucariota)", "5 (Monera, Protista, Fungi, Plantae, Animalia)", "3 (Bacteria, Archaea y Eukarya)", "6"], c: 2, ex: "3 dominios: Bacteria, Archaea (procariotas pero genética distinta), Eukarya. Reinos son clasificación más fina. → <b>Las otras:</b> (A) \"2\" agrupa demasiado; (B) \"5\" son los REINOS, no dominios; (D) inexistente."},
  {st: 'En un ecosistema, los organismos AUTÓTROFOS:', opts: ["Consumen otros organismos para obtener energía y materia orgánica ya formada", "Fijan energía solar o química y producen materia orgánica propia", "Descomponen materia muerta y devuelven nutrientes inorgánicos al suelo y al agua", "Ocupan el nivel superior de la cadena trófica al alimentarse de los herbívoros"], c: 1, ex: "Auto + trofos = se alimentan a sí mismos. Producen materia orgánica desde inorgánica (CO₂) usando luz (foto) o química (quimio). Base de cadenas tróficas. → <b>Las otras:</b> (A) son los heterótrofos; (C) descomponedores son saprófitos; (D) los autótrofos son la base de la cadena, no el nivel superior: los carnívoros se alimentan de los herbívoros."}
]);

registerExercises('biologia', '2', [
  {st: '¿Cuál función es exclusiva de células EUCARIONTES?', opts: ["La fotosíntesis, realizada con clorofila sobre membranas internas", "La respiración celular, que oxida la glucosa para obtener ATP", "La síntesis de proteínas a partir de ARN mensajero", "El transporte de vesículas entre el retículo y el Golgi"], c: 3, ex: "Transporte vesicular requiere endomembranas y citoesqueleto, ambos AUSENTES en procariotas. → <b>Las otras:</b> (A) cianobacterias hacen fotosíntesis; (B) y (C) son universales en todos los seres vivos."},
  {st: '¿Qué proceso ocurre en VEGETALES pero NO en animales?', opts: ["La fijación de CO₂ en los cloroplastos", "La respiración celular en las mitocondrias", "La división celular por mitosis y meiosis", "La transcripción y la traducción del ADN"], c: 0, ex: "Cloroplastos solo en plantas/algas (animales no fijan CO₂). → <b>Las otras:</b> (B), (C) y (D) son universales en eucariotas: también ocurren en animales."},
  {st: 'Indica la opción que represente nivel SUBCELULAR EXCLUSIVO de vegetales:', opts: ["Almidón y ADN con histonas", "Cloroplastos y vacuola central", "Ribosomas y cloroplastos", "Complejo de Golgi y pared celular"], c: 1, ex: "Cloroplastos + vacuola central = exclusivos de plantas. → <b>Las otras:</b> (A) ADN+histonas también animal; (C) ribosomas universales; (D) Golgi en todos los eucariotas."},
  {st: '¿Cuál es EXCLUSIVA de un PROCARIONTE?', opts: ['Unicelulares y se dividen por mitosis', 'Pueden reproducirse sexualmente', 'ADN circular no asociado a histonas', 'Pared de quitina'], c: 2, ex: 'ADN circular sin histonas = procariota. → Por qué las otras están mal: (A) procariotas hacen FISIÓN BINARIA, no mitosis; (B) reproducción sexual es eucariota; (D) quitina es de hongos.'},
  {st: 'Al comparar células eucariotas y procariotas:', opts: ["Los procariotas se dividen por fisión binaria y los eucariotas por mitosis o meiosis", "Ambas sintetizan sus proteínas en ribosomas adheridos al retículo rugoso", "Las eucariotas pueden ser autótrofas o heterótrofas y las procariotas solo heterótrofas", "En las eucariotas la glucólisis ocurre en las mitocondrias y en las procariotas en el citosol"], c: 0, ex: "Procariotas: fisión binaria. Eucariotas somáticas: mitosis. Eucariotas gaméticas: meiosis. → <b>Las otras:</b> (B) REG solo en eucariotas; (C) hay procariotas autótrofas (cianobacterias); (D) glucólisis ocurre en CITOSOL en ambas."},
  {st: '¿Qué diferencia una célula PROCARIONTE autótrofa de una EUCARIONTE autótrofa?', opts: ["Mitocondrias", "Pared celular", "Permeabilidad selectiva", "Citoplasma"], c: 0, ex: "Solo eucariotas tienen mitocondrias (procariotas hacen respiración en su membrana). → <b>Las otras:</b> (B) pared en ambas (peptidoglicano vs celulosa); (C) la membrana plasmática es selectivamente permeable en ambas; (D) ambas tienen citoplasma."},
  {st: 'La compartimentalización celular en eucariotas permite:', opts: ["Mezclar libremente las reacciones en toda la célula, sin barreras entre procesos", "Especializar microambientes (pH, enzimas) para procesos específicos en cada organela", "Reducir el tamaño de la célula al repartir las funciones en estructuras pequeñas", "Reemplazar la membrana plasmática por las membranas de las organelas internas"], c: 1, ex: "Compartimentalización = innovación clave eucariota: cada organela tiene su microambiente (lisosoma pH 4.5, mitocondria con gradientes para ATP, etc.). → <b>Las otras:</b> (A) lo opuesto: las membranas separan las reacciones; (C) eucariotas son MÁS GRANDES; (D) la membrana plasmática sigue presente."}
]);

registerExercises('biologia', '3', [
  {st: 'Si se aísla una partícula infecciosa SOLO con proteínas, podría tratarse de:', opts: ["Un prion", "Un viroide", "Un virus", "Un retrovirus"], c: 0, ex: "Prion = solo proteína mal plegada (sin ácido nucleico). Causa enfermedades neurodegenerativas (Creutzfeldt-Jakob, vacas locas). → <b>Las otras:</b> (B) viroide = solo ARN; (C) virus = ác. nucleico + cápside; (D) retrovirus = ARN + transcriptasa."},
  {st: '¿Cuál afirmación sobre los virus es CORRECTA?', opts: ["Sintetizan sus proteínas con sus propios genes y ribosomas", "La cápside es una membrana que intercambia sustancias con el medio", "En el ciclo lítico el ADN viral se integra al ADN de la célula huésped", "Requieren ribosomas celulares para sintetizar las proteínas virales"], c: 3, ex: "Virus NO tienen ribosomas → parásitos intracelulares OBLIGADOS, usan los de la célula. → <b>Las otras:</b> (A) no tienen ribosomas propios; (B) cápside es proteica, no membrana; (C) integración es del ciclo LISOGÉNICO."},
  {st: 'Los viroides son agentes infecciosos que:', opts: ["Son ARN pequeños con cápside proteica, que infectan plantas", "Son proteínas mal plegadas que infectan el sistema nervioso", "Son ARN circulares pequeños, sin cápside, que infectan plantas", "Son priones sin ácido nucleico, que infectan plantas"], c: 2, ex: "Viroide = ARN circular pequeño SIN cápside, infecta plantas (papa, tubérculos). → <b>Las otras:</b> (A) sin cápside: los viroides son ARN desnudo; (B) son los priones quienes afectan SNC animal; (D) priones son proteína y no infectan plantas; viroides son ARN."},
  {st: 'En un ciclo viral en eucariontes, el orden general es:', opts: ["Adsorción → penetración → biosíntesis → decapsidación → ensamblaje → liberación", "Adsorción → entrada → decapsidación → biosíntesis → ensamblaje → liberación", "Entrada → adsorción → decapsidación → biosíntesis → ensamblaje → liberación de viriones", "Adsorción → entrada → biosíntesis → ensamblaje → decapsidación → liberación de viriones"], c: 1, ex: "Orden: (1) adsorción a receptor, (2) entrada/penetración, (3) decapsidación, (4) biosíntesis, (5) ensamblaje, (6) liberación (lisis o gemación). → <b>Las otras:</b> (A) pone la biosíntesis antes de la decapsidación, y sin liberar el genoma de la cápside no hay síntesis; (C) la entrada va después de la adsorción: primero el virus se une al receptor; (D) la decapsidación va antes de la biosíntesis, no después del ensamblaje."},
  {st: 'Los retrovirus se caracterizan por:', opts: ["Tienen ARN y transcriptasa inversa, que convierte el ARN en ADN", "Tienen ADN de doble cadena y ADN polimerasa, que copia el ADN viral en la célula", "Tienen ADN y transcriptasa inversa, que convierte el ADN viral en ARN", "Tienen ARN y solo infectan plantas, sin transcriptasa inversa"], c: 0, ex: "Retrovirus (VIH) tienen ARN + transcriptasa inversa → ADN que se integra al genoma. → <b>Las otras:</b> (B) su material genético es ARN, no ADN de doble cadena; (C) la transcriptasa inversa va de ARN a ADN, no al revés, y el genoma es ARN; (D) infectan animales mayoritariamente y justamente se definen por la transcriptasa inversa."},
  {st: 'Diferencia entre ciclo LÍTICO y LISOGÉNICO:', opts: ["Lítico: integra el ADN viral al genoma y lisa la célula; lisogénico: replica sin integrarse", "Lítico: ocurre solo en eucariotas; lisogénico: ocurre solo en procariotas", "Lítico: es más lento y no rompe la célula; lisogénico: replica rápido y la lisa", "Lítico: replica y lisa la célula; lisogénico: el ADN viral se integra al genoma huésped"], c: 3, ex: "Lítico = replicación rápida + lisis (ROMPE célula al liberar viriones). Lisogénico = profago integrado al cromosoma, replica con él silenciosamente. → <b>Las otras:</b> (A) invierte los ciclos: la integración es del lisogénico y la lisis del lítico; (B) ambos ocurren en procariotas (fagos); (C) el lítico es el rápido y el que rompe la célula, el lisogénico es silencioso."},
  {st: '¿Cuál NO es característica de los virus?', opts: ['Material genético (ADN o ARN)', 'Cápside proteica', 'Ribosomas propios', 'Replicación en célula huésped'], c: 2, ex: 'Virus NO tienen ribosomas → necesitan los del huésped. → Por qué las otras están mal: (A) (B) (D) sí tienen.'}
]);

registerExercises('biologia', '4', [
  {st: 'El ADN y el ARN se DIFERENCIAN entre sí por:', opts: ["Adenina", "Timina", "Grupos fosfato", "Citosina"], c: 1, ex: "Solo ADN tiene timina; ARN tiene URACILO en su lugar. Otra diferencia: azúcar (desoxirribosa vs ribosa). → <b>Las otras:</b> (A) y (D) están en ambos; (C) ambos tienen grupos fosfato que unen los nucleótidos."},
  {st: '¿En qué opción TODAS las moléculas son de RESERVA energética?', opts: ["Glucógeno / colágeno / almidón", "Glucógeno / hemoglobina / triglicéridos", "Glucógeno / triglicéridos / almidón", "Celulosa / glucógeno / almidón"], c: 2, ex: "Reserva: glucógeno (animal), almidón (vegetal), triglicéridos (grasa). → <b>Las otras:</b> (A) colágeno es ESTRUCTURAL, no de reserva; (B) hemoglobina transporta oxígeno, no es reserva; (D) celulosa es ESTRUCTURAL (pared vegetal)."},
  {st: 'Una proteína receptor con 5 cadenas polipeptídicas. ¿Mayor nivel estructural?', opts: ["Terciaria", "Secundaria", "Primaria", "Cuaternaria"], c: 3, ex: "Cuaternaria = >1 cadena. 5 cadenas → cuaternaria. → <b>Las otras:</b> (A) terciaria sería 1 cadena plegada; (B) secundaria son α-hélice/β-plegada; (C) primaria es la secuencia."},
  {st: '¿En qué grupo TODAS son proteínas (su hidrólisis libera AMINOÁCIDOS)?', opts: ["Hemoglobina / carrier de glucosa", "Insulina / colesterol", "Acilglicérido / bomba de protones", "Enzimas hidrolíticas / glucógeno"], c: 0, ex: "Hemoglobina + carrier de glucosa = ambas proteínas → liberan aminoácidos. → <b>Las otras:</b> (B) colesterol es lípido; (C) acilglicérido es lípido; (D) glucógeno es polisacárido (libera glucosa)."},
  {st: 'En las moléculas biológicas, la energía disponible para metabolismo está en:', opts: ["Puentes de hidrógeno", "Enlaces covalentes", "Uniones iónicas", "Fuerzas de Van der Waals"], c: 1, ex: "Energía química principal en enlaces covalentes (C-C, C-H). Romperlos (oxidación) libera energía. → <b>Las otras:</b> (A), (C) y (D) son uniones débiles con mucha menos energía aprovechable que un enlace covalente."},
  {st: 'Un nucleótido está formado por:', opts: ["Una hexosa, una base nitrogenada y de uno a tres fosfatos", "Una pentosa y una base nitrogenada, sin ningún grupo fosfato", "Una pentosa, una base nitrogenada y de uno a tres fosfatos", "Una pentosa, un aminoácido y de uno a tres fosfatos"], c: 2, ex: "Nucleótido = pentosa + base (A,T,G,C,U) + 1-3 fosfatos. Ej: ATP = adenina + ribosa + 3 fosfatos. → <b>Las otras:</b> (A) el azúcar de los nucleótidos es una pentosa (ribosa o desoxirribosa), no una hexosa; (B) pentosa + base sin fosfato es un nucleósido, no un nucleótido; (D) los aminoácidos forman péptidos y no entran en un nucleótido, que lleva una base nitrogenada."},
  {st: 'Los lípidos anfipáticos que conforman membranas son:', opts: ["Triglicéridos", "Esteroides", "Ceras", "Fosfolípidos"], c: 3, ex: "Fosfolípidos = anfipáticos: cabeza polar + 2 colas apolares. Forman bicapas. → Por qué las otras están mal: (A) (B) (C) no anfipáticos en mismo grado, no estructurales."}
]);

registerExercises('biologia', '5', [
  {st: 'Para AUMENTAR la fluidez de membranas:', opts: ["Más colas saturadas en los fosfolípidos de la bicapa", "Bajar la temperatura del medio que rodea a la célula", "Más colas insaturadas en los fosfolípidos", "Mayor pH del medio extracelular que rodea a la célula"], c: 2, ex: "Las colas insaturadas tienen dobles enlaces que doblan la cadena → impiden el empaquetamiento → más fluidez. → <b>Las otras:</b> (A) las colas saturadas son rectas, se empaquetan mejor y bajan la fluidez; (B) bajar la temperatura disminuye la fluidez; (D) el pH no es un determinante directo de la fluidez."},
  {st: 'Una célula AUMENTA volumen en solución desconocida. ¿Cuál?', opts: ["Igual concentración (isotónica)", "2× más diluida (hipotónica)", "50% más concentrada", "2× más concentrada"], c: 1, ex: "Aumenta volumen → entra agua → medio externo HIPOTÓNICO (menos solutos afuera). Solución diluida = hipotónica. → Por qué las otras están mal: (A) sin cambio; (C) (D) hipertónicas → célula se encoge."},
  {st: '¿Qué pasa con el transporte de CO₂ si se BLOQUEAN todas las proteínas de canal?', opts: ["CO₂ pasa normal por difusión simple", "CO₂ requiere energía", "CO₂ no puede ingresar pero sí salir", "CO₂ no puede salir pero sí ingresar"], c: 0, ex: "CO₂ es pequeño y apolar → difusión SIMPLE por la bicapa, sin canales. → Por qué las otras están mal: (B) la difusión simple es pasiva; (C) (D) descripciones absurdas (canales no son selectivos por dirección)."},
  {st: 'En comunicación celular, el LIGANDO:', opts: ["Recorre distancias cortas en la señalización endocrina", "Es hidrofílico y se une a un receptor citosólico", "Es la respuesta que se desencadena en la célula diana", "Puede unirse a un receptor proteico en la célula blanco"], c: 3, ex: "El ligando se une al receptor (proteína) en la célula blanco. → <b>Las otras:</b> (A) la señalización endocrina es de LARGAS distancias, por la sangre; (B) los ligandos hidrofílicos tienen receptor de MEMBRANA (no citosólico); (C) la respuesta es lo que ocurre tras la unión, no el ligando."},
  {st: 'Colesterol y proteína integral de canal en una membrana cumplen, respectivamente:', opts: ["Recepción de señales y aporte de energía para la célula", "Receptor de señales y transporte de sustancias polares", "Estabilizar la membrana y transportar o catalizar", "Aporte de energía para la célula y transporte de iones"], c: 2, ex: "El colesterol estabiliza la membrana y regula su fluidez. Las proteínas integrales pueden ser canal/transportador o enzima. → <b>Las otras:</b> (A) el colesterol no es receptor ni da energía, y la proteína de canal tampoco aporta energía; (B) el colesterol no es receptor; (D) el colesterol no aporta energía, aunque el canal sí transporta iones."},
  {st: 'INGRESO de K⁺ en CONTRA de gradiente al citosol es:', opts: ["Exergónico no anabólico", "Endergónico no anabólico", "Endergónico y anabólico", "Endergónico y catabólico"], c: 1, ex: "Contra gradiente → endergónico (requiere ATP). Pero NO es anabólico (no sintetiza moléculas grandes), solo mueve un ion. → Por qué las otras están mal: (A) endergónico (requiere energía); (C) (D) no es ni anabólico ni catabólico."},
  {st: 'Comunicación celular con señal en sangre a LARGAS distancias:', opts: ["Endocrina", "Autocrina", "Paracrina", "Sináptica"], c: 0, ex: "Endocrina = hormonas en sangre, larga distancia. → Por qué las otras están mal: (B) la propia célula; (C) células vecinas (corta distancia); (D) entre neuronas (cortísima)."}
]);

registerExercises('biologia', '6', [
  {st: 'Sin citoesqueleto en una célula eucariota animal, se afectaría:', opts: ["Difusión simple", "Síntesis de proteínas citosólicas", "Respiración celular", "División celular"], c: 3, ex: "División requiere huso mitótico (microtúbulos) + citoquinesis (microfilamentos). → Por qué las otras están mal: (A) difusión es por la membrana; (B) síntesis ocurre en ribosomas; (C) respiración en mitocondrias."},
  {st: '¿Qué funciones se relacionan con MICROTÚBULOS?', opts: ["Formación de flagelos y transporte de vesículas", "Contracción muscular y transporte de vesículas", "Contracción muscular y formación de cilios y flagelos", "División del citoplasma y transporte de vesículas"], c: 0, ex: "Microtúbulos: cilios, flagelos, transporte vesicular (kinesina/dineína), huso mitótico. → <b>Las otras:</b> (B) la contracción muscular es de actina y miosina (MICROFILAMENTOS), aunque el transporte de vesículas sí es de microtúbulos; (C) la contracción muscular es de microfilamentos, aunque cilios y flagelos sí son de microtúbulos; (D) la división del citoplasma (citoquinesis) la hace el anillo contráctil de MICROFILAMENTOS de actina."},
  {st: 'El sistema de Golgi:', opts: ['Polimeriza y glicosila proteínas', 'Forma vesículas de secreción', 'Sintetiza triglicéridos y colesterol', 'Sintetiza glucosa'], c: 1, ex: 'Golgi modifica (glicosilación, fosforilación) y EMPAQUETA proteínas en vesículas. → Por qué las otras están mal: (A) glicosila pero no polimeriza; (C) eso es REL; (D) glucosa se hace en cloroplastos (fotosíntesis).'},
  {st: 'Si se elimina REL en células animales:', opts: ["No se sintetizan triglicéridos ni ATP", "No se almacena Ca²⁺ ni se sintetizan proteínas de membrana", "No hay síntesis de colesterol ni detoxificación", "No se sintetizan fosfolípidos ni enzimas lisosomales"], c: 2, ex: "REL: lípidos (colesterol, fosfolípidos, triglicéridos), detoxificación, almacén de Ca²⁺. → Por qué las otras están mal: ATP en mitocondrias; proteínas y enzimas lisosomales en REG."},
  {st: 'Las células del estómago secretan pepsinógeno (proteína). Tienen muy desarrollado:', opts: ["REL y Golgi", "Mitocondrias y REL", "Lisosomas y REG", "REG y Golgi"], c: 3, ex: "Cadena para secretar proteína: REG (síntesis) → Golgi (modificación) → vesícula → exocitosis. → Por qué las otras están mal: REL es para lípidos; mitocondrias para ATP; lisosomas para digestión."},
  {st: 'Los filamentos del citoesqueleto encargados de contracción muscular y citoquinesis:', opts: ["Microfilamentos (actina)", "Microtúbulos (tubulina)", "Filamentos intermedios", "Fibras de laminina"], c: 0, ex: "Actina + miosina = contracción muscular y anillo contráctil de citoquinesis. → <b>Las otras:</b> (B) los microtúbulos forman el huso y llevan el transporte vesicular; (C) los filamentos intermedios dan soporte mecánico; (D) la laminina es una proteína de la matriz extracelular, no un filamento del citoesqueleto."},
  {st: 'La matriz extracelular (ECM) en tejidos animales:', opts: ["Es un medio acuoso de sales y azúcares, sin proteínas, donde las células flotan sin anclarse", "Contiene colágeno, elastina y proteoglicanos; las células se anclan por integrinas", "No cumple ninguna función mecánica y solo transmite señales químicas entre células vecinas", "Es una estructura exclusiva de las plantas, formada por celulosa y pectinas que rodean la célula"], c: 1, ex: "ECM = red de macromoléculas (colágeno, elastina, fibronectina, proteoglicanos). Integrinas anclan células a ECM. Da soporte y señales. → <b>Las otras:</b> (A) la ECM es una red rica en proteínas, no un medio de sales y azúcares; (C) la ECM da soporte mecánico además de señales; (D) las plantas tienen pared celular, no ECM como los animales."}
]);

registerExercises('biologia', '7', [
  {st: '¿Cuál enunciado es aplicable a TODAS las enzimas?', opts: ["Si se altera su estructura terciaria pueden perder actividad", "Aceleran únicamente las reacciones catabólicas de degradación", "La especificidad la determina el sitio alostérico de cada una", "Pierden su actividad catalítica después de cada reacción"], c: 0, ex: "Actividad depende de estructura 3D (sitio activo). Desnaturalización = pierde actividad. → <b>Las otras:</b> (B) catalizan ANABOLISMO también; (C) la especificidad es del SITIO ACTIVO (no alostérico); (D) NO se consumen: quedan intactas y se reutilizan."},
  {st: 'En reacción enzimática X→Y:', opts: ["A mayor concentración de sustrato se forma menos producto", "Vmax sigue aumentando al subir la concentración de sustrato", "La reacción solo ocurre a la temperatura óptima de la enzima en la célula", "Vmax corresponde a la saturación de las enzimas por sustrato"], c: 3, ex: "A altas [sustrato], todas las enzimas saturadas → Vmax (depende de [enzima], no de sustrato). → <b>Las otras:</b> (A) más sustrato → más producto (hasta saturar); (B) Vmax depende de [enzima] y no sigue subiendo con el sustrato; (C) ocurre fuera del óptimo, solo más lento."},
  {st: '¿Cuál reacción es CATABÓLICA?', opts: ['Glicina + alanina + prolina → tripéptido', 'Glucosa + glucosa → maltosa', 'Glucosa + O₂ → CO₂ + H₂O', 'Glicerol + 3 ácidos grasos → triglicérido'], c: 2, ex: 'Oxidación de glucosa = catabolismo (rompe molécula grande, libera energía). → Por qué las otras están mal: (A) (B) (D) son anabolismo (sintetizan moléculas grandes desde pequeñas).'},
  {st: 'Inhibidores COMPETITIVOS:', opts: ["Se unen a un sitio distinto del activo, como reguladores alostéricos", "Se unen al sitio activo, compiten con el sustrato y bajan la velocidad", "Reducen la cantidad de sustrato disponible al unirse a él", "Se unen de forma irreversible al sitio activo y lo inactivan"], c: 1, ex: "Competitivo = compite con sustrato por SITIO ACTIVO. Se revierte aumentando [sustrato]. → <b>Las otras:</b> (A) un regulador alostérico se une a un sitio DISTINTO del activo; (C) el inhibidor se une a la enzima, no al sustrato, y no lo consume; (D) el competitivo es REVERSIBLE: el exceso de sustrato lo desplaza."},
  {st: 'El ATP es "moneda energética" porque:', opts: ["Acopla reacciones exergónicas (lo producen) con endergónicas (lo consumen)", "Es la principal molécula que almacena energía química de forma estable en la célula", "Es un nucleótido de alta energía que se almacena en las membranas de todas las células", "Se produce sobre todo en el anabolismo y se consume en el catabolismo"], c: 0, ex: "ATP integra: catabolismo lo carga, anabolismo lo gasta. Es la unidad de intercambio energético celular. → <b>Las otras:</b> (B) el ATP no se almacena de forma estable: las reservas son glucógeno y grasas, y hay otras moléculas energéticas (NADH, GTP); (C) es un nucleótido, pero no se almacena en las membranas: se produce y se consume de continuo; (D) es al revés: el catabolismo lo produce y el anabolismo lo consume."},
  {st: 'Una reacción libera energía neta. ¿A qué proceso podría corresponder?', opts: ["Fotosíntesis completa", "Síntesis de polipéptido", "Glicerol + ácido graso → monoglicérido", "Respiración celular"], c: 3, ex: "Exergónica = libera energía → catabolismo. Respiración oxida glucosa, libera ~30-32 ATP. → Por qué las otras están mal: (A) (B) (C) son anabolismo (endergónicas, requieren energía)."},
  {st: 'En reacciones óxido-reducción, OXIDARSE significa:', opts: ["Ganar electrones (o ganar H, o perder oxígeno)", "Compartir electrones sin transferirlos", "Perder electrones (o perder H, o ganar oxígeno)", "Perder oxígeno o ganar H, sin pasar electrones"], c: 2, ex: "Oxidación = pérdida de electrones (o de H, o ganancia de O). Reducción = ganancia. Siempre van juntas (acopladas). → <b>Las otras:</b> (A) es REDUCCIÓN, justo lo opuesto; (B) compartir electrones es formar un enlace covalente, no una oxidación; (D) perder O y ganar H es REDUCCIÓN."}
]);

registerExercises('biologia', '8', [
  {st: 'En célula muscular SIN O₂, la glucosa se degrada a:', opts: ["Solo ácido pirúvico", "Ácido láctico", "Etanol", "CO₂"], c: 1, ex: "Sin O₂, músculo hace fermentación LÁCTICA: glucosa → 2 pirúvico → 2 lactato (regenera NAD+). En levaduras es etanol. → Por qué las otras están mal: (A) pirúvico es intermediario; (C) eso es en levaduras; (D) requiere O₂."},
  {st: 'Orden CORRECTO de etapas de fotosíntesis:', opts: ["Captación de luz / síntesis de glucosa / ruptura del agua", "Liberación de O₂ / síntesis de glucosa / síntesis de ATP", "Liberación de O₂ / incorporación de CO₂ / síntesis de hidratos", "Captación de luz / degradación de ATP / fijación de CO₂"], c: 2, ex: "Fase clara: fotólisis del agua (libera O₂) + ATP/NADPH. Fase oscura: ciclo de Calvin (fija CO₂ por RuBisCO) y sintetiza glucosa. → <b>Las otras:</b> (A) la glucosa se sintetiza al final, en el ciclo de Calvin, y no antes de la ruptura del agua; (B) el ATP se sintetiza en la fase clara, antes de la síntesis de glucosa; (D) el ATP se produce y se consume en el ciclo de Calvin, no se degrada para fijar el CO₂."},
  {st: 'Si los carbonos del pirúvico se marcan radiactivamente, aparecerán en:', opts: ["ATP", "Glucosa", "NADH", "CO₂"], c: 3, ex: "Pirúvico se DESCARBOXILA en oxidación y ciclo de Krebs → C sale como CO₂. → Por qué las otras están mal: (A) ATP no incorpora esos C; (B) glucosa no se forma de pirúvico en respiración; (C) NADH lleva H, no C."},
  {st: 'Mitocondrias aisladas con NAD+, FAD, ADP+Pi. Para completar oxidación se agrega:', opts: ["Ácido pirúvico y O₂", "Glucosa, O₂ y CO₂", "Glucosa, luz y CO₂", "Ácido pirúvico y CO₂"], c: 0, ex: "La mitocondria recibe pirúvico (NO glucosa, la glucólisis es citosólica) y necesita O₂ (aceptor final de electrones). → <b>Las otras:</b> (B) la mitocondria no usa glucosa directamente y el CO₂ es producto, no reactivo; (C) no usa glucosa directamente y la luz es de la fotosíntesis; (D) el CO₂ es producto, no reactivo, y falta el O₂."},
  {st: 'Los autótrofos contrarrestan aumento de CO₂ atmosférico porque:', opts: ["Degradan el CO₂ en los cloroplastos para obtener energía útil", "Usan el CO₂ en la fase bioquímica de la fotosíntesis (Calvin)", "Usan el CO₂ en el ciclo de Krebs para sintetizar glucosa", "Disminuyen la formación de CO₂ en el ciclo de Calvin"], c: 1, ex: "Calvin: RuBisCO fija CO₂ → biomasa. → <b>Las otras:</b> (A) lo fijan, no lo degradan; (C) Krebs es respiración (LIBERA CO₂) y no sintetiza glucosa; (D) Calvin lo CONSUME, no hay formación de CO₂ que disminuir."},
  {st: 'En un cloroplasto, la fase fotoquímica:', opts: ["En el estroma, Calvin transforma el O₂ en glucosa", "En el estroma, Krebs transforma el CO₂ en glucosa", "En los tilacoides ocurre la fotólisis del agua (H₂O → O₂)", "En los tilacoides se fija el CO₂ con la enzima RuBisCO"], c: 2, ex: "Fotoquímica = en TILACOIDES. Fotólisis del agua libera O₂. La fijación de CO₂ es en estroma (Calvin). → <b>Las otras:</b> (A) Calvin es la fase bioquímica, no la fotoquímica, y usa CO₂, no O₂; (B) Krebs es respiración, no forma parte de la fotosíntesis; (D) la fijación de CO₂ con RuBisCO es en el estroma, no en tilacoides."},
  {st: '¿Dónde ocurre la GLUCÓLISIS en eucariotas?', opts: ["Matriz mitocondrial", "Membrana interna mitocondrial", "Núcleo", "Citosol"], c: 3, ex: "Glucólisis: CITOSOL (pre-mitocondria evolutivamente). No requiere O₂ ni organelas. Si hay O₂ después, el pirúvico entra a mitocondria. → Por qué las otras están mal: (A) (B) Krebs y cadena respiratoria; (C) núcleo es para ADN."},
  {st: 'En respiración aeróbica, el aceptor FINAL de electrones de la cadena es:', opts: ["O₂", "NAD+", "FAD", "CO₂"], c: 0, ex: "O₂ recibe electrones al final + H+ → H₂O. Sin O₂, cadena se detiene, no hay fosforilación oxidativa. Por eso respiramos. → Por qué las otras están mal: (B) (C) son intermediarios (transportadores); (D) producto del ciclo de Krebs, no aceptor."}
]);

/* =================== SEGUNDO PARCIAL =================== */

registerExercises('biologia', '9', [
  {st: '¿Qué estructura del núcleo está formada por DOS membranas concéntricas con poros?', opts: ["Lámina nuclear", "Nucléolo (zona densa)", "Envoltura nuclear", "Cromatina condensada"], c: 2, ex: "La envoltura nuclear (carioteca) tiene 2 membranas (interna + externa); la externa se continúa con el REG y tiene ribosomas. Los poros nucleares regulan el tráfico. → <b>Las otras:</b> (A) la lámina es una malla de filamentos proteicos por dentro de la envoltura; (B) el nucléolo NO tiene membrana; (D) la cromatina es ADN + histonas."},
  {st: 'El nucléolo se caracteriza por:', opts: ["Estar rodeado por una membrana propia, igual que el núcleo", "Ser donde se sintetiza el ARNr y se ensamblan las subunidades ribosomales", "Ser donde se sintetizan las histonas y se arman los nucleosomas", "Ser el sitio donde se replica todo el ADN de la célula antes de la división"], c: 1, ex: "Nucléolo = región densa SIN membrana donde se hace ARNr y se ensamblan subunidades ribosomales. → <b>Las otras:</b> (A) NO tiene membrana; (C) las histonas se sintetizan en el citosol y entran al núcleo; (D) la replicación es en todo el núcleo durante S."},
  {st: 'Sobre el transporte por los poros nucleares es CORRECTO:', opts: ["Es selectivo y las moléculas grandes se transportan con gasto de GTP", "Es siempre por difusión simple, incluso para las proteínas grandes", "Es unidireccional: solo entran moléculas al núcleo, nunca salen", "Las importinas sacan el ARNm al citoplasma gastando GTP"], c: 0, ex: "Los poros son muy selectivos; la mayoría de moléculas requiere transporte activo con GTP. → <b>Las otras:</b> (B) solo iones y moléc. pequeñas difunden; (C) hay entrada (NLS, importinas) y salida (NES, exportinas); (D) las importinas IMPORTAN, no exportan."},
  {st: 'La unidad básica de la cromatina es:', opts: ["El cromosoma metafásico, con sus dos cromátides hermanas", "El solenoide, fibra de 30 nm formada por nucleosomas", "La fibra de bucles, con asas de ADN ancladas a proteínas", "El nucleosoma (ADN con un octámero de histonas)"], c: 3, ex: "Nucleosoma = ADN enrollado en un octámero de 8 histonas (2 H2A, 2 H2B, 2 H3, 2 H4). H1 estabiliza. → <b>Las otras:</b> (A) (B) (C) son niveles SUPERIORES de empaquetamiento, no la unidad básica."},
  {st: 'Comparando eucromatina y heterocromatina:', opts: ["La heterocromatina es laxa y se transcribe mucho; la eucromatina es condensada y silente", "La eucromatina es laxa y se transcribe; la heterocromatina es condensada y silente", "Ambas tienen el mismo grado de compactación y se transcriben por igual", "La eucromatina existe solo en procariotas; la heterocromatina existe solo en eucariotas"], c: 1, ex: "Eucromatina = abierta = activa. Heterocromatina = condensada = silente. → <b>Las otras:</b> (A) lo opuesto; (C) tienen niveles MUY distintos de compactación; (D) ambas son tipos de cromatina eucariota, y los procariotas no tienen cromatina como tal."},
  {st: 'Un cromosoma DUPLICADO típico (después de S) tiene:', opts: ["1 cromátide con 1 centrómero y 2 telómeros, sin copia del ADN", "2 cromátides hermanas idénticas unidas por un centrómero y 4 telómeros", "4 cromátides hermanas unidas por 2 centrómeros y 8 telómeros", "2 cromátides distintas, una de cada progenitor, unidas por un centrómero"], c: 1, ex: "Tras S: 2 cromátides hermanas idénticas (= 2 moléculas de ADN), 1 centrómero (donde se unen), 4 telómeros (extremos). → <b>Las otras:</b> (A) esa es la situación ANTES de S, con una sola molécula de ADN; (C) duplicar el ADN da 2 cromátides, no 4, y queda un solo centrómero; (D) las cromátides hermanas son copias idénticas, no una de cada progenitor."},
  {st: 'Una célula es 2n=8. ¿Qué significa?', opts: ["Tiene 8 cromosomas en total, agrupados en 4 pares de homólogos", "Tiene 8 cromosomas en total, agrupados en 8 pares de homólogos", "Tiene 2 cromosomas, agrupados en 8 grupos de homólogos", "Es haploide, con 8 cromosomas sin pares de homólogos"], c: 0, ex: "\"2n\" = diploide (2 juegos). \"8\" = total de cromosomas. Si 2n=8 → 4 pares de homólogos. → <b>Las otras:</b> (B) 8 pares serían 16 cromosomas (2n=16); (C) sin sentido, el número da el total de cromosomas y no el de grupos; (D) eso sería n=8, y 2n indica diploide."},
  {st: 'Diferencia entre cromosomas homólogos y cromátides hermanas:', opts: ["Homólogos: copias idénticas por replicación. Hermanas: uno de cada progenitor, con los mismos genes", "Homólogos: uno de cada progenitor, con genes distintos. Hermanas: copias idénticas por replicación", "Son sinónimos: ambos términos nombran las copias idénticas que se forman al replicarse el ADN", "Homólogos: uno de cada progenitor, mismos genes. Hermanas: copias idénticas por replicación"], c: 3, ex: "Homólogos = pareja del mismo cromosoma con origen distinto (mismos genes, los alelos pueden diferir). Hermanas = clones por replicación. → <b>Las otras:</b> (A) está dado vuelta: las copias por replicación son las hermanas; (B) los homólogos tienen los MISMOS genes (en el mismo orden), aunque con alelos posiblemente distintos; (C) no son sinónimos, y los homólogos no son copias entre sí."}
]);

registerExercises('biologia', '10', [
  {st: '¿Qué es un gen, según la definición actual?', opts: ["Una secuencia de ADN que codifica una proteína o un ARN funcional", "Una proteína estructural que almacena la información hereditaria celular", "Cualquier región del ADN, tenga o no un producto funcional", "Solo las secuencias de ADN que codifican enzimas del metabolismo celular"], c: 0, ex: "Hoy se considera gen a cualquier secuencia de ADN que dé un producto funcional: proteína O ARN (ARNt, ARNr, ARNnc). → <b>Las otras:</b> (B) los genes no son proteínas, son secuencias de ADN; (C) demasiado amplio, no toda región del ADN es un gen; (D) demasiado restringido: hay genes de proteínas no enzimáticas y de ARN."},
  {st: 'Durante la transcripción, la enzima ARN polimerasa:', opts: ["Lee la hebra molde de 5' a 3' y sintetiza ARN de 3' a 5'", "Usa desoxirribonucleótidos como sustrato", "Necesita un cebador de ARN para empezar", "Lee la hebra molde de 3' a 5' y sintetiza ARN de 5' a 3'"], c: 3, ex: "ARN pol: lee 3'→5', sintetiza 5'→3'. Usa RIBOnucleótidos trifosfatados, no desoxi. NO necesita cebador. → Por qué las otras están mal: (A) direcciones invertidas; (B) eso es la ADN pol; (C) eso es la ADN pol."},
  {st: 'En el ARN, la base que reemplaza a la timina del ADN es:', opts: ['Adenina', 'Citosina', 'Uracilo', 'Guanina'], c: 2, ex: 'ADN: A T G C. ARN: A U G C. La T se reemplaza por U. Pareja A-U en transcripción. → Por qué las otras están mal: A, G, C están en ambos ácidos nucleicos.'},
  {st: 'En la transcripción, los sustratos son:', opts: ["Aminoácidos", "Ribonucleósidos trifosfatados (ATP, UTP, GTP, CTP)", "Desoxirribonucleótidos trifosfatados (dATP, dTTP, dGTP, dCTP)", "Solo ATP"], c: 1, ex: "Para hacer ARN se usan ribonucleósidos trifosfatados: ATP, UTP, GTP, CTP. Aportan los nucleótidos Y la energía. → Por qué las otras están mal: (A) son para traducción; (C) son para REPLICACIÓN del ADN; (D) hacen falta los 4."},
  {st: '¿Cuál de los siguientes es un proceso de maduración del ARNm en eucariotas?', opts: ['Capping en 5\'', 'Adición de cola poli-A en 3\'', 'Splicing (eliminación de intrones)', 'Todas las anteriores'], c: 3, ex: 'El pre-ARNm sufre 3 modificaciones en el núcleo antes de salir: capping (5\'), poli-A (3\') y splicing. → Por qué las otras están mal: cada una sola es incompleta.'},
  {st: 'En un gen eucariota, los intrones:', opts: ["Codifican proteínas pequeñas que se unen a las codificadas por los exones", "Se transcriben y quedan en el ARNm maduro, donde regulan la traducción celular", "Son exclusivos de los genes procariotas y se eliminan por splicing", "Son secuencias no codificantes que se eliminan del pre-ARNm en el splicing"], c: 3, ex: "Intrones = \"intra-génicos\" no codificantes. Se transcriben pero se sacan del pre-ARNm en el splicing. Solo los EXONES (codificantes) quedan en el ARNm maduro. → <b>Las otras:</b> (A) no codifican; (B) se eliminan en el splicing y no quedan en el ARNm maduro; (C) son típicos de eucariotas, no de procariotas."},
  {st: 'En procariotas, la traducción es CO-TRANSCRIPCIONAL porque:', opts: ["Tienen un núcleo pequeño y los ribosomas ingresan a traducir el ARNm", "Usan el ADN directamente como molde en los ribosomas, sin ARNm", "No hay membrana nuclear: el ARNm ya se traduce mientras se transcribe", "Sus ribosomas están en el nucleoide y traducen solo ARN ya procesado"], c: 2, ex: "Sin núcleo, transcripción y traducción ocurren en el mismo lugar al mismo tiempo (citoplasma). En eucariotas son post-transcripcionales (núcleo separa). → <b>Las otras:</b> (A) los procariotas no tienen núcleo; (B) sí hay ARNm, la traducción lee ARNm y no ADN; (D) el ARNm procariota casi no se procesa y se traduce mientras se transcribe, sin esperar."},
  {st: 'El splicing ALTERNATIVO permite:', opts: ["Que cada gen produzca solo una proteína, porque se empalman todos los exones", "Obtener varias proteínas de un mismo pre-ARNm al combinar exones distintos", "Que se transcriba todo el ADN de la célula, incluidas las regiones intergénicas", "Eliminar los exones del pre-ARNm y conservar solo los intrones en el ARN maduro"], c: 1, ex: "Splicing alternativo elige distintas combinaciones de exones → varias proteínas de un mismo gen. Por eso 20.000 genes → 90.000 proteínas en humanos. → <b>Las otras:</b> (A) lo opuesto: justamente permite más de una proteína por gen; (C) no tiene que ver con cuánto ADN se transcribe; (D) elimina INTRONES, no exones."}
]);

registerExercises('biologia', '11', [
  {st: '¿Cuántos codones tiene el código genético y cuántos son STOP?', opts: ["20 codones en total, 17 codifican aminoácidos y 3 son STOP", "64 codones en total y todos codifican aminoácidos", "4 codones en total, uno por cada base, y 1 es STOP", "64 codones en total, 61 codifican aminoácidos y 3 son STOP"], c: 3, ex: "4³=64 combinaciones. 61 codifican aminoácidos. 3 son STOP: UAA, UAG, UGA. → <b>Las otras:</b> (A) 20 es la cantidad de aminoácidos, no de codones; (B) hay 3 STOP que no codifican aminoácido; (C) un codón es un triplete: se cuenta de a tres bases, no de a una."},
  {st: 'El codón de INICIO de la traducción es:', opts: ["AUG (metionina)", "UGA (señal de STOP)", "GCC (alanina)", "UAC (tirosina)"], c: 0, ex: "AUG inicia toda traducción y codifica para metionina. UGA es STOP. → <b>Las otras:</b> (B) es un codón STOP, termina la traducción; (C) codifica para alanina, no inicia; (D) UAC codifica tirosina, no inicia la traducción."},
  {st: '"El código genético es DEGENERADO" significa:', opts: ["Es ambiguo: un codón puede codificar varios aminoácidos", "Distintos codones pueden codificar el mismo aminoácido", "Tiene errores", "No es universal"], c: 1, ex: "Degenerado = redundante = varios codones sinónimos. Ej: CCA, CCC, CCU, CCG = todos prolina. → Por qué las otras están mal: (A) lo opuesto (es específico, NO ambiguo); (C) el código no tiene errores: la redundancia lo hace robusto frente a mutaciones; (D) sí es universal."},
  {st: 'Durante la traducción, ¿dónde llega el ARNt cargado con su aminoácido?', opts: ["Sitio P del ribosoma", "Citosol libre", "Sitio A del ribosoma", "Lisosoma"], c: 2, ex: "Sitio A (aminoacilo) = donde llega el nuevo ARNt cargado. Sitio P (peptidilo) = donde está la cadena creciente. → <b>Las otras:</b> (A) el ARNt iniciador llega al P, los demás al A → (B) (D) no son sitios de traducción."},
  {st: 'Si el codón del ARNm es 5\'-AUG-3\', el anticodón del ARNt es:', opts: ["5'-AUG-3'", "5'-UAC-3'", "5'-TAC-3'", "3'-UAC-5'"], c: 3, ex: "Anticodón es complementario Y antiparalelo: codón 5'AUG3' → anticodón 3'UAC5' (= 5'CAU3'). → <b>Las otras:</b> (A) igual al codón → (B) misma dirección que el codón → (C) tiene T (sería ADN)."},
  {st: 'Una inserción de un nucleótido en el ADN genera, con frecuencia:', opts: ["Un corrimiento del marco de lectura que altera todos los codones siguientes al sitio", "Una proteína idéntica, porque el código genético es redundante para ese cambio", "Un cambio de un solo aminoácido, porque se modifica únicamente un codón", "Ningún efecto sobre la proteína, porque la ARN polimerasa descarta el nucleótido extra"], c: 0, ex: "Insertar o eliminar un nucleótido CORRE el marco de lectura: todos los codones siguientes cambian. Suele dar una proteína no funcional. → <b>Las otras:</b> (B) eso sería una sustitución silenciosa, no una inserción → (C) eso sería una sustitución con cambio de un aminoácido, no una inserción → (D) suele tener un efecto grave, y la ARN polimerasa no corrige ese nucleótido."},
  {st: 'Una proteína que será SECRETADA por exocitosis comienza su síntesis en:', opts: ["Ribosomas libres, y sin péptido señal sigue sintetizándose en el citosol", "Ribosomas libres, y al detectarse un péptido señal pasa al REG y continúa allí", "Ribosomas libres, y al detectarse una secuencia de importación pasa a la mitocondria", "Ribosomas propios del aparato de Golgi, que reciben el ARNm directamente desde el núcleo"], c: 1, ex: "Todas las proteínas inician en ribosomas libres. Si los primeros aminoácidos forman un péptido SEÑAL hidrofóbico → el ribosoma se acopla al REG → continúa la síntesis ahí → Golgi → vesícula → exocitosis. → <b>Las otras:</b> (A) sin péptido señal la proteína queda en el citosol y no se secreta → (C) esa secuencia dirige a la mitocondria, no a la secreción → (D) el Golgi no sintetiza proteínas, las procesa."},
  {st: 'Las proteínas que actúan en el CITOSOL o en la MITOCONDRIA se sintetizan:', opts: ["En ribosomas unidos al REG, porque llevan un péptido señal que los dirige al retículo", "En el aparato de Golgi, donde se sintetizan y luego se envían a su destino final", "En ribosomas libres del citosol, porque no presentan péptido señal", "En el lisosoma, que tiene sus propios ribosomas y enzimas para fabricarlas"], c: 2, ex: "Sin péptido señal hidrofóbico → ribosomas libres. Destinos: citosol, núcleo, mitocondrias, peroxisomas, cloroplastos. → <b>Las otras:</b> (A) el REG es para proteínas con péptido señal (membrana, secreción, lisosomas) → (B) el Golgi procesa proteínas, no las sintetiza → (D) el lisosoma tampoco hace síntesis de proteínas."}
]);

registerExercises('biologia', '12', [
  {st: 'Una neurona y una célula epitelial son tan distintas pero comparten:', opts: ["Distinto ADN, porque cada tejido pierde los genes que no usa", "Distintos cromosomas, porque el número varía entre los tejidos", "El mismo ADN, pero con distintos genes activos en cada tipo celular", "Ningún gen, porque cada tipo celular tiene un genoma exclusivo"], c: 2, ex: "Todas las células somáticas de un organismo tienen el MISMO ADN. La diferenciación se debe a expresión génica diferencial: distintos patrones de genes activos. → <b>Las otras:</b> (A) las células no pierden genes al diferenciarse, tienen el mismo genoma → (B) todas las somáticas tienen el mismo número de cromosomas → (D) comparten todo el ADN."},
  {st: 'La METILACIÓN del ADN generalmente:', opts: ["Activa la transcripción al aflojar la cromatina que rodea al ADN", "Silencia al gen y condensa la cromatina (epigenética)", "Corta el ADN en el promotor para que la ARN polimerasa lo lea", "Ocurre solo durante la mitosis y se pierde al terminar la división"], c: 1, ex: "Metilación del ADN (CH₃) → silenciamiento + condensación a heterocromatina. La acetilación de histonas ACTIVA. → <b>Las otras:</b> (A) acetilación activa, metilación silencia → (C) la metilación agrega grupos CH₃, no corta el ADN → (D) es una marca estable y heredable, típica de eucariotas, que no se pierde al terminar la mitosis."},
  {st: 'El splicing ALTERNATIVO permite que:', opts: ["Un mismo gen genere varias proteínas distintas, según qué exones se empalmen", "Los exones se eliminen del ARN y la proteína se arme únicamente con los intrones", "Los procariontes empalmen los genes de un operón en un único ARNm", "Se dupliquen los exones en el ADN y cada copia dé una proteína nueva"], c: 0, ex: "Splicing alternativo = distintas combinaciones de exones → variantes proteicas. Explica por qué 20.000 genes humanos hacen 90.000 proteínas. → <b>Las otras:</b> (B) el splicing elimina INTRONES y conserva exones → (C) el splicing ocurre sólo en eucariotas → (D) ocurre sobre el ARN, no modifica el ADN."},
  {st: 'En el operón LAC de E. coli, EN AUSENCIA de lactosa:', opts: ["El represor se despega del operador y se transcriben las enzimas de degradación", "La ARN polimerasa transcribe los genes lac y las enzimas degradan la lactosa", "La lactosa se une al operador y bloquea la transcripción de los genes lac", "El represor se une al operador e impide que se transcriban los genes del operón lac"], c: 3, ex: "Sin lactosa: represor unido al operador → bloquea la ARN pol → genes silenciados. Tiene sentido: no hace falta fabricar las enzimas si no hay sustrato. → <b>Las otras:</b> (A) eso pasa EN PRESENCIA de lactosa, cuando el inductor libera al represor → (B) lo mismo: sin lactosa los genes lac no se transcriben → (C) la lactosa no se une al operador, se une al represor, y sin ella el represor queda activo."},
  {st: '¿Qué hace la LACTOSA cuando aparece en el medio de una bacteria con operón lac?', opts: ["Se une al operador y bloquea el paso de la ARN polimerasa hacia los genes lac", "Se une a la ARN polimerasa y la inactiva, de modo que los genes lac se apagan", "Se une al represor y lo despega del operador, permitiendo transcribir", "Aumenta la síntesis del represor, que se acumula sobre el operador lac"], c: 2, ex: "Lactosa = INDUCTOR: se une al represor, lo desactiva, libera el operador. La ARN pol puede entonces transcribir los genes que codifican enzimas para degradar la lactosa. → <b>Las otras:</b> (A) lo opuesto: la lactosa no se une al operador, libera al represor → (B) la lactosa no inhibe a la ARN polimerasa, la libera → (D) no aumenta el represor, lo desactiva."},
  {st: 'El ARNm policistrónico (que codifica varias proteínas) es típico de:', opts: ["Eucariontes, porque su ARNm se procesa y codifica varias proteínas a la vez", "Procariontes, donde varios genes de un operón se transcriben juntos", "Virus solamente, ya que sólo ellos juntan varios genes en un mismo ARNm", "Ningún organismo, porque cada ARNm codifica una sola proteína"], c: 1, ex: "Procariotas → operones → ARNm policistrónico (1 ARNm con varias proteínas). Eucariotas: 1 gen = 1 ARNm = 1 proteína (en general). → <b>Las otras:</b> (A) los eucariontes son monocistrónicos → (C) sí existen, y son típicos de procariontes y no sólo de virus → (D) sí existen, en procariontes."},
  {st: '¿Qué proteína marca a otras proteínas para que sean degradadas en el proteasoma?', opts: ["Ubiquitina", "Chaperona", "Quinasa", "Helicasa"], c: 0, ex: "Ubiquitina = etiqueta que dirige proteínas dañadas o ya innecesarias al proteasoma para su hidrólisis. → <b>Las otras:</b> (B) las chaperonas ayudan al plegamiento → (C) las quinasas fosforilan → (D) la helicasa abre el ADN en la replicación."}
]);

registerExercises('biologia', '13', [
  {st: 'El orden CORRECTO de las subfases de la interfase es:', opts: ['M → G1 → S', 'G1 → S → G2', 'S → G1 → G2', 'G2 → S → G1'], c: 1, ex: 'Interfase: G1 (crecimiento) → S (síntesis/replicación de ADN) → G2 (preparación división). Luego viene la fase M (mitosis + citocinesis). → Por qué las otras están mal: orden incorrecto.'},
  {st: 'Una célula en G0:', opts: ["Está en mitosis, con los cromosomas condensados y alineados en el ecuador", "Acaba de duplicar su ADN y se prepara para el punto de control de G2", "Está fuera del ciclo y no se divide, como las neuronas adultas", "Es una célula tumoral que ignora los controles y se divide sin parar"], c: 2, ex: "G0 = células que abandonan el ciclo y no se dividen. Ej: neuronas adultas, miocitos esqueléticos. → <b>Las otras:</b> (A) lo opuesto: una célula en mitosis está dividiéndose → (B) eso es G2, tras la fase S → (D) las tumorales se dividen DEMASIADO (lo opuesto a G0)."},
  {st: 'Si una célula es 2n=6 en G2, ¿cuántas cromátides totales tiene?', opts: ["6 cromátides", "3 cromátides", "24 cromátides", "12 cromátides"], c: 3, ex: "En G1: 6 cromosomas con 1 cromátide = 6 cromátides. Tras S: cada cromosoma duplicado tiene 2 cromátides hermanas. En G2: 6 cromosomas × 2 = 12 cromátides totales. → <b>Las otras:</b> (A) 6 es la cuenta de G1, antes de duplicar el ADN → (B) 3 es el número haploide (n), no una cuenta de cromátides → (C) 24 multiplica de más: duplica dos veces."},
  {st: 'El punto de control de G1 verifica principalmente:', opts: ["Tamaño celular, nutrientes y daños en el ADN antes de comprometerse a dividirse", "Que todo el ADN se haya duplicado completo y sin errores antes de entrar en mitosis", "Que el huso mitótico esté bien formado y los cromosomas unidos a él", "Que la mitosis haya terminado y se separen las dos células hijas"], c: 0, ex: "G1 checkpoint: ¿tengo tamaño? ¿nutrientes? ¿ADN sin daños? ¿señales externas? Decide si entra a S o va a G0. → <b>Las otras:</b> (B) es el checkpoint de G2 → (C) es el checkpoint M → (D) el de M chequea la alineación, no la terminación."},
  {st: 'Los factores promotores del ciclo celular (FPS, FPM) están formados por:', opts: ["Una quinasa (Cdk) sola, que se activa al unirse al ATP celular", "Una quinasa (Cdk) unida a una ciclina que la regula y la activa", "Una ciclina sola, que fosforila las proteínas que hacen avanzar el ciclo", "ATP y GTP, que aportan la energía para pasar de una fase a la siguiente"], c: 1, ex: "Quinasa sola = inactiva. Ciclina sola = inerte. Sólo el COMPLEJO quinasa-ciclina es activo (factor promotor) y puede fosforilar proteínas para avanzar el ciclo. → <b>Las otras:</b> (A) la Cdk sola no es activa, necesita a la ciclina → (C) la ciclina no tiene actividad de quinasa, es la Cdk la que fosforila → (D) son moléculas energéticas, no factores promotores."},
  {st: 'La replicación del ADN es SEMICONSERVATIVA porque:', opts: ["Una de las dos moléculas hijas conserva las dos hebras originales y la otra es toda nueva", "Cada molécula hija mezcla fragmentos de hebras viejas y fragmentos nuevos en ambas hebras", "Cada nueva molécula de ADN tiene una hebra vieja (molde) y una hebra nueva", "Las hebras originales se degradan y cada molécula hija se arma sólo con nucleótidos nuevos"], c: 2, ex: "Semiconservativa: tras la replicación, cada doble hélice nueva tiene 1 hebra original + 1 hebra recién sintetizada. → <b>Las otras:</b> (A) es el modelo conservativo, descartado experimentalmente → (B) es el modelo dispersivo, también descartado → (D) las hebras originales no se degradan, se usan como molde."},
  {st: 'La enzima ADN polimerasa necesita un CEBADOR porque:', opts: ["No puede leer la hebra molde sin cebador, que es quien abre la doble hélice", "Necesita un OH 5' libre al cual unir el nucleótido, y el cebador lo ofrece", "El cebador la activa enzimáticamente: sin él su sitio activo no funciona", "No puede iniciar una cadena de cero: sólo agrega nucleótidos a un OH 3' libre"], c: 3, ex: "La ADN pol solo PROLONGA. Necesita un primer (cebador de ARN) que ofrezca un OH 3' libre para empezar. Luego se elimina y se reemplaza por ADN. → <b>Las otras:</b> (A) sí puede leer el molde, y quien abre la hélice es la helicasa → (B) agrega nucleótidos al OH 3', no al 5' → (C) el cebador no es un activador enzimático, es el punto de partida de la cadena."},
  {st: 'Comparando replicación y transcripción:', opts: ["Ambas usan los mismos sustratos: desoxinucleótidos y la misma polimerasa", "La replicación copia las dos hebras del ADN; la transcripción copia una sola hebra de un gen", "La transcripción es bidireccional y arranca en un origen de replicación (ORI)", "La replicación copia solo un gen y produce ARN; la transcripción duplica todo el ADN"], c: 1, ex: "Replicación: duplica TODO el ADN (las 2 hebras). Transcripción: copia 1 hebra molde de un GEN puntual a ARN. → <b>Las otras:</b> (A) la replicación usa desoxinucleótidos y la transcripción ribonucleótidos, con enzimas distintas → (C) la transcripción es UNIdireccional desde el +1, y el ORI es de la replicación → (D) está todo invertido: la replicación produce ADN y copia el genoma completo."},
  {st: 'La proteína p53 ("guardián del genoma") cuando detecta daño en el ADN:', opts: ["Acelera la división celular para diluir el daño entre las células hijas hasta repararlo", "Detiene el ciclo para reparar y, si el daño es irreparable, induce apoptosis", "No responde al daño en el ADN, sino sólo al tamaño y a los nutrientes", "Activa la replicación del ADN dañado para que se corrija en la fase S"], c: 1, ex: "p53 es un supresor de tumores: frena el ciclo en el checkpoint para dar tiempo a reparar; si no se puede reparar, induce apoptosis (muerte programada). Si p53 está mutado, la célula se divide con ADN dañado → tumores (mutada en muchísimos cánceres). → <b>Las otras:</b> (A) lo opuesto a su función protectora: dividirse con daño propaga las mutaciones → (C) sí responde al daño, es el control clave → (D) frena la replicación del ADN dañado, no la activa."}
]);

registerExercises('biologia', '14', [
  {st: 'La mitosis se produce en:', opts: ["Células somáticas, que se dividen para crecer y reparar los tejidos", "Sólo en células germinales de las gónadas, para formar gametos", "Sólo en procariotas, que se dividen por mitosis y no por fisión", "Sólo en gametos, que se dividen para originar el cigoto"], c: 0, ex: "Mitosis: división de células somáticas (crecimiento, reparación). Meiosis: sólo células germinales para formar gametas. → <b>Las otras:</b> (B) la formación de gametos es meiosis → (C) los procariotas hacen fisión binaria → (D) los gametos no se dividen, se fusionan en la fecundación."},
  {st: 'Al final de la mitosis, las células hijas son:', opts: ["Dos células genéticamente distintas de la madre, por crossing over", "Cuatro células haploides con combinaciones nuevas de alelos", "Dos células sin núcleo, porque la envoltura nuclear no se rearma", "Dos células genéticamente idénticas a la madre y con la misma ploidía"], c: 3, ex: "Mitosis: 1 célula 2n → 2 células 2n GENÉTICAMENTE IDÉNTICAS. Meiosis: 1 célula 2n → 4 células n distintas. → <b>Las otras:</b> (A) el crossing over es de la meiosis, no de la mitosis → (B) eso es meiosis → (C) los glóbulos rojos pierden el núcleo, pero no es el resultado normal de la mitosis."},
  {st: 'En la METAFASE de la mitosis, los cromosomas:', opts: ["Empiezan a condensarse y la envoltura nuclear comienza a desarmarse", "Se separan hacia los polos, arrastrados por las fibras del huso", "Se alinean en el plano ecuatorial y están máximamente condensados", "Se descondensan y se forma una nueva envoltura nuclear a su alrededor"], c: 2, ex: "Metafase: alineación en la placa metafásica + máxima condensación. Por eso los cariotipos se obtienen de células en metafase. → <b>Las otras:</b> (A) eso es profase → (B) eso es anafase → (D) eso es telofase."},
  {st: 'En la ANAFASE I de la MEIOSIS se separan:', opts: ["Las cromátides hermanas, que se separan hacia polos opuestos del huso mitótico", "Los cromosomas homólogos, mientras las cromátides hermanas siguen juntas", "Los centríolos, que se separan y migran hacia polos opuestos", "Los nucleolos, que se dividen en dos y se reparten entre las hijas"], c: 1, ex: "Meiosis I es REDUCCIONAL: separa homólogos → de 2n a n. Las cromátides hermanas se separan en anafase II. → <b>Las otras:</b> (A) eso es anafase II (o la anafase mitótica) → (C) los centríolos no son lo que se separa en esta etapa → (D) los nucleolos se desarman en la profase, no se reparten por división."},
  {st: 'El CROSSING OVER ocurre en:', opts: ["Profase I de la meiosis, con intercambio de fragmentos entre cromosomas homólogos apareados", "Profase de la mitosis, con intercambio de fragmentos entre los cromosomas replicados", "Anafase II de la meiosis, cuando las cromátides hermanas se separan y se recombinan", "Citocinesis, con intercambio de fragmentos entre los cromosomas de las células hijas"], c: 0, ex: "Crossing over (entrecruzamiento) = intercambio de fragmentos entre cromátides NO hermanas de homólogos. Es la principal fuente de variabilidad genética. → <b>Las otras:</b> (B) en la mitosis no hay entrecruzamiento entre homólogos → (C) en la anafase II las cromátides sólo se separan, no se recombinan → (D) la citocinesis reparte el citoplasma, no intercambia fragmentos de ADN."},
  {st: 'En un cruzamiento Aa × Aa (A domina sobre a), la proporción FENOTÍPICA esperada en la F2 es:', opts: ["1 AA : 2 Aa : 1 aa", "1 dominante : 3 recesivo", "1 dominante : 1 recesivo", "3 dominante : 1 recesivo"], c: 3, ex: "Aa × Aa: gametas A y a de cada uno. Punnett: AA, Aa, Aa, aa = genotipos 1:2:1. Fenotipos: AA y Aa expresan A (dominante), aa expresa a → 3:1. → <b>Las otras:</b> (A) es la proporción genotípica, no la fenotípica → (B) invierte la proporción: los dominantes son la mayoría → (C) es la proporción de un cruzamiento prueba (Aa × aa), no de Aa × Aa."},
  {st: 'Si un individuo es HETEROCIGOTA para el gen del color de ojos (Aa):', opts: ["Tiene dos alelos iguales, ambos dominantes, y por eso expresa el carácter dominante", "Tiene un solo alelo del gen, heredado de uno de los progenitores, y lo expresa", "Tiene dos alelos distintos, uno dominante y otro recesivo, y expresa el dominante", "Sólo puede producir gametas con A, porque el alelo dominante se transmite siempre a los hijos"], c: 2, ex: "Heterocigota = alelos distintos (Aa). Expresa el dominante. Produce gametas A y a en proporción 50:50. → <b>Las otras:</b> (A) eso es homocigota → (B) tiene 2 alelos, uno de cada progenitor → (D) produce los dos tipos de gametas, A y a, y el dominante no se transmite siempre."},
  {st: 'La fuente PRINCIPAL de variabilidad genética en la meiosis NO es:', opts: ["El crossing over en profase I", "La replicación del ADN en S (es muy precisa)", "La distribución independiente de homólogos en anafase I", "La fecundación posterior (combinación de gametas)"], c: 1, ex: "La replicación es muy fiel: NO genera variabilidad. Variabilidad: crossing over + distribución independiente + fecundación. → <b>Las otras:</b> (A) (C) (D) sí son fuentes de variabilidad."},
  {st: 'En la ovogénesis humana, a partir de UNA ovogonia se obtiene:', opts: ["1 óvulo viable y 2 o 3 cuerpos polares que luego degeneran", "4 óvulos viables, por una citocinesis igual que reparte el citoplasma", "2 óvulos viables y 2 cuerpos polares, tras la primera división", "4 cuerpos polares que degeneran, sin óvulo viable alguno"], c: 0, ex: "Ovogénesis: citocinesis DESIGUAL (todo el citoplasma a una sola célula). 1 ovogonia → 1 óvulo grande + cuerpos polares pequeños que mueren. En espermatogénesis sí se obtienen 4 espermatozoides. → <b>Las otras:</b> (B) 4 células viables es el resultado de la espermatogénesis, no de la ovogénesis → (C) tras la primera división hay 1 ovocito y 1 cuerpo polar, y no se obtienen 2 óvulos → (D) siempre se forma un óvulo, lo que se pierde es el resto del material."},
  {st: 'La meiosis en el ovocito humano se DETIENE en:', opts: ["Anafase I, hasta la pubertad, y telofase II, hasta que ocurre la fecundación", "No tiene detenciones: avanza sin pausa y completa las dos divisiones meióticas antes del nacimiento", "Metafase I, durante toda la infancia, y anafase II, hasta el momento de la ovulación", "Profase I, desde la vida intrauterina hasta la pubertad, y metafase II, hasta la fecundación"], c: 3, ex: "Ovogénesis tiene 2 detenciones largas: profase I durante años (desde el 5.º mes intrauterino) y metafase II (que se completa SOLO si hay fecundación). → <b>Las otras:</b> (A) las detenciones no son en anafase I ni en telofase II → (B) sí tiene detenciones, y son largas → (C) la primera pausa es en profase I y la segunda en metafase II, no en esas etapas."},
  {st: 'Diferencia entre DOMINANCIA INCOMPLETA y CODOMINANCIA:', opts: ["Incompleta: ambos alelos se expresan a la vez (grupo sanguíneo AB). Codominancia: fenotipo intermedio (rojo + blanco = rosa)", "Incompleta: fenotipo intermedio (rojo + blanco = rosa). Codominancia: ambos alelos se expresan a la vez (grupo sanguíneo AB)", "Incompleta: el alelo dominante tapa por completo al recesivo. Codominancia: el heterocigota muestra un fenotipo intermedio entre los dos", "Incompleta: sólo se da en plantas, como el color de las flores. Codominancia: sólo se da en animales, como el grupo sanguíneo AB"], c: 1, ex: "Incompleta: el heterocigota muestra un fenotipo MEZCLADO/intermedio. Codominancia: muestra LOS DOS al mismo tiempo, distinguibles. Ej clásico: el grupo AB tiene antígenos A y B en su glóbulo rojo, no uno intermedio. → <b>Las otras:</b> (A) tiene los conceptos intercambiados → (C) describe la dominancia completa en la incompleta, y atribuye a la codominancia un fenotipo intermedio → (D) ambas se dan en plantas y en animales, y no se distinguen por el grupo de seres vivos."},
  {st: 'En el sistema sanguíneo ABO, una persona del grupo AB tiene genotipo:', opts: ["I^A I^A (homocigota: expresa sólo el antígeno A en la membrana del glóbulo rojo)", "ii (recesivo: sin antígenos A ni B, y con anticuerpos anti-A y anti-B en el plasma)", "I^A I^B (codominancia: expresa antígeno A y B en la misma membrana)", "I^B i (heterocigota: expresa el antígeno B porque I^B domina sobre i)"], c: 2, ex: "Grupo AB = un alelo I^A + un alelo I^B; ambos son codominantes y se expresan simultáneamente. Grupo 0 = ii (recesivo, sin antígeno). → <b>Las otras:</b> (A) sería grupo A → (B) sería grupo 0 → (D) sería grupo B."},
  {st: 'Querés saber si un ratón negro es AA o Aa. ¿Qué cruce hacés (cruzamiento prueba)?', opts: ["Cruzarlo con un homocigota dominante (AA). Si aparecen hijos grises, era Aa; si todos son negros, era AA", "Cruzarlo con un homocigota recesivo (aa). Si todos son grises, era Aa; si aparecen negros, era AA", "Cruzarlo con un homocigota recesivo (aa). En los dos casos nacen negros y grises, así que no se puede saber", "Cruzarlo con un homocigota recesivo (aa). Si aparecen descendientes grises, era Aa; si todos son negros, era AA"], c: 3, ex: "Cruzamiento prueba/retrocruza: × aa. Si era AA → todas Aa (100 % negro). Si era Aa → 50 % Aa (negro) + 50 % aa (gris). La aparición de UN solo gris ya delata heterocigota. → <b>Las otras:</b> (A) con AA nunca nacen grises, sea cual sea su genotipo, así que no distingue → (B) invierte el resultado: si era AA, todos los hijos son Aa y NEGROS → (C) los dos casos dan resultados distintos: sólo si era Aa aparecen grises."},
  {st: 'Un varón se dice HEMICIGOTA para un gen ligado al X porque:', opts: ["Tiene un solo alelo del gen, en su único X, porque el Y carece de ese gen", "Tiene dos alelos del gen, uno en el X y otro en el Y, y expresa el dominante", "Tiene el gen duplicado, porque el Y lleva una copia idéntica a la del X", "No tiene el gen, porque el único X del varón está inactivado por completo"], c: 0, ex: "Hemicigota = un solo alelo presente. Los varones XY tienen un solo X → expresan cualquier alelo del X, aunque sea recesivo. Por eso enfermedades como hemofilia y daltonismo son más frecuentes en varones. → <b>Las otras:</b> (B) el Y no tiene el gen, así que no hay segundo alelo → (C) no hay copia en el Y, el gen no está duplicado → (D) el varón sí tiene el gen, y su único X está activo (la inactivación del X es de las mujeres)."},
  {st: 'Un padre daltónico (X^d Y) tiene hijos con una madre sana NO portadora (X^D X^D). ¿Qué hijos esperás?', opts: ["Todos los varones daltónicos (X^d Y), porque heredan del padre el alelo X^d junto con el cromosoma Y", "Todas las hijas daltónicas (X^d X^D), porque el X^d del padre se expresa con otro X", "Los hijos varones salen sanos (X^D Y) y todas las hijas salen sanas portadoras (X^D X^d)", "50 % de varones daltónicos (X^d Y) y 50 % sanos (X^D Y), y todas las hijas sanas no portadoras (X^D X^D)"], c: 2, ex: "X^d Y × X^D X^D: los hijos varones heredan Y del padre + X^D de la madre = X^D Y (sanos). Las hijas heredan X^d del padre + X^D de la madre = X^D X^d (sanas portadoras). El padre daltónico NO transmite el alelo a sus hijos varones (les pasa Y), pero SÍ a todas sus hijas como portadoras. → <b>Las otras:</b> (A) el varón recibe el Y del padre y el X de la madre, que es X^D, así que ninguno es daltónico → (B) el alelo d es recesivo: con el X^D de la madre las hijas no son daltónicas, son portadoras → (D) todos los varones heredan X^D de la madre y son sanos (no hay mitad daltónica), y todas las hijas reciben X^d del padre: son portadoras, no X^D X^D."},
  {st: 'La NO-DISYUNCIÓN durante la meiosis puede producir:', opts: ["Siempre gametas con la cantidad normal de cromosomas, aunque con distintos alelos", "Cuerpos polares funcionales, capaces de ser fecundados y de formar un cigoto", "Gametas con cromosomas de más o menos, o aneuploidías como la trisomía 21", "Mayor variabilidad genética útil, al combinar más alelos distintos en las gametas"], c: 2, ex: "No-disyunción: los cromosomas (homólogos en anafase I, o cromátides en anafase II) NO se separan bien. Resultado: una gameta con un cromosoma de más, otra con uno de menos. Si se fecunda → trisomía 21 (Down), monosomía X (Turner), XXY (Klinefelter), etc. → <b>Las otras:</b> (A) justamente altera el número de cromosomas de las gametas → (B) los cuerpos polares no son funcionales ni se fecundan → (D) no aporta variabilidad útil: produce aneuploidías, que suelen ser perjudiciales."}
]);

registerExercises('biologia', '15', [
  {st: '¿Quién o qué evoluciona?', opts: ["Cada individuo a lo largo de su vida, al adquirir los caracteres que le sirven", "Las moléculas de ADN dentro de una célula, que mutan al envejecer la célula", "Una especie dentro de un solo individuo, cuando éste acumula mutaciones favorables", "Las poblaciones, por cambios en la frecuencia de alelos entre generaciones"], c: 3, ex: "La evolución ocurre en POBLACIONES, no en individuos. Es el cambio en las frecuencias de alelos generación tras generación. → <b>Las otras:</b> (A) los individuos no evolucionan, y los caracteres adquiridos no se heredan (eso era Lamarck) → (B) las moléculas pueden mutar, pero no es la escala en la que ocurre la evolución → (C) una especie no está contenida en un individuo: requiere población."},
  {st: 'Para Darwin, la SELECCIÓN NATURAL requiere:', opts: ["Variabilidad heredable, sobreproducción y selección diferencial (los más aptos dejan más descendencia)", "Variabilidad adquirida en vida, que se transmite a los hijos por el uso o desuso de los órganos", "Sólo mutaciones beneficiosas, que aparecen cuando el ambiente las demanda y luego se heredan", "Un ambiente estable, donde los individuos más fuertes eliminan a los más débiles de la población"], c: 0, ex: "Selección natural: 1) variabilidad, 2) herencia, 3) sobreproducción, 4) selección diferencial → cambian las frecuencias de alelos. → <b>Las otras:</b> (B) es la idea de Lamarck: los caracteres adquiridos no se heredan → (C) las mutaciones son al azar, no aparecen cuando se las necesita, y no son todas beneficiosas → (D) no requiere un ambiente estable (el cambio ambiental impulsa la selección) y no se trata de fuerza sino de dejar más descendencia."},
  {st: 'La principal fuente de variabilidad genética en la teoría sintética es:', opts: ["La selección natural, que crea los alelos favorables que el ambiente necesita", "La mutación, es decir, cambios al azar en el ADN, que crean alelos nuevos", "La deriva génica, que genera alelos nuevos en las poblaciones pequeñas", "El uso y desuso de los órganos, que genera caracteres que se heredan"], c: 1, ex: "Mutación = fuente primaria de variabilidad genética. Recombinación, flujo génico y deriva génica reorganizan y modifican esa variabilidad. La selección natural FILTRA, no genera. → <b>Las otras:</b> (A) la selección natural filtra la variabilidad que ya existe, no crea alelos → (C) la deriva cambia frecuencias por azar, pero no crea alelos nuevos → (D) los caracteres adquiridos por uso o desuso no se heredan."},
  {st: 'Las mutaciones genéticas son:', opts: ["Dirigidas por las necesidades del individuo, que las genera cuando el ambiente lo exige", "Siempre beneficiosas, porque aparecen sólo cuando mejoran la adaptación del organismo", "Eventos al azar, y la selección natural favorece luego a las útiles en el ambiente", "Siempre dañinas, porque alteran la secuencia del ADN y la función de la proteína"], c: 2, ex: "Las mutaciones son aleatorias, no dirigidas. La selección natural NO es al azar: filtra lo aleatorio según ventajas adaptativas. → <b>Las otras:</b> (A) no son dirigidas por las necesidades del individuo → (B) no aparecen cuando se las necesita, y las hay neutras y dañinas → (D) hay mutaciones beneficiosas, neutras y dañinas."},
  {st: 'La TEORÍA ENDOSIMBIÓTICA (Lynn Margulis) explica el origen de:', opts: ["Los virus, a partir de fragmentos de ADN que escaparon de células eucariotas ancestrales", "El núcleo y el retículo, por plegamiento de la membrana plasmática hacia el interior", "Los priones, a partir de proteínas mal plegadas que se transmiten entre las células", "Las mitocondrias y los cloroplastos, de procariotas englobadas como simbiontes"], c: 3, ex: "Una eucariota ancestral englobó procariotas aerobias → mitocondrias. Otra englobó cianobacterias → cloroplastos. Evidencia: doble membrana, ADN circular propio, ribosomas 70S, fisión binaria. → <b>Las otras:</b> (A) el origen de los virus no se explica con esta teoría → (B) el núcleo y el retículo se explican por invaginación de la membrana, no por endosimbiosis → (C) los priones son proteínas infecciosas y no se relacionan con esta teoría."},
  {st: '¿Qué evidencia apoya la teoría endosimbiótica?', opts: ["Las mitocondrias tienen ADN circular propio y ribosomas procariotas 70S, como las bacterias", "Las mitocondrias tienen una sola membrana y ribosomas eucariotas 80S propios", "Las mitocondrias realizan fotosíntesis, igual que los cloroplastos que se les parecen", "Las mitocondrias se sintetizan en el REG y se envían a su destino por vesículas"], c: 0, ex: "Mitocondrias y cloroplastos tienen: ADN circular propio, ribosomas 70S (como bacterias), doble membrana, se dividen por fisión binaria. Todo apunta a un origen procariota. → <b>Las otras:</b> (B) tienen doble membrana y ribosomas 70S, no 80S → (C) las mitocondrias NO fotosintetizan → (D) se hacen por fisión binaria, no en el REG."},
  {st: 'La ESPECIACIÓN ALOPÁTRICA requiere:', opts: ["Que las dos poblaciones convivan en el mismo lugar y se aíslen reproductivamente", "Una barrera geográfica que separe poblaciones, que luego evolucionan independientemente", "Que haya flujo génico constante entre las poblaciones, que divergen igualmente", "Sólo cambios cromosómicos, como la poliploidía, en una población sin barreras"], c: 1, ex: "Alopátrica = otra patria: barrera geográfica (montaña, río) → aislamiento → evolución divergente → aislamiento reproductivo → especies distintas. La simpátrica es sin barrera geográfica. → <b>Las otras:</b> (A) eso es simpátrica → (C) el flujo génico constante homogeneiza a las poblaciones y no deja que se separen → (D) los cambios cromosómicos sin barrera son un mecanismo de especiación simpátrica."},
  {st: 'La SELECCIÓN NATURAL:', opts: ["Genera variabilidad genética al crear los alelos que el ambiente actual requiere", "Sólo actúa en bacterias, que tienen ciclos de vida cortos y muchas generaciones", "No genera variabilidad: la filtra y favorece a los más adaptados al ambiente actual", "Sólo actúa sobre caracteres adquiridos en vida, que se transmiten luego a la descendencia"], c: 2, ex: "Selección natural = filtro: no inventa variabilidad, elige entre la que existe (generada por mutación y recombinación). Favorece a los más aptos al ambiente. → <b>Las otras:</b> (A) los alelos nuevos los generan la mutación y la recombinación → (B) actúa en todos los seres vivos → (D) los caracteres adquiridos NO se heredan (eso era Lamarck)."}
]);
